package com.auditlog.service.crypto;
import com.auditlog.service.entity.AuditEvent;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.nio.charset.StandardCharsets;import java.security.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.stereotype.Component;
@Component public class CryptoService{private final ObjectMapper om;public CryptoService(ObjectMapper om){this.om=om;}
 public String canonical(JsonNode node){try{return om.writer().with(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS).writeValueAsString(sort(node));}catch(Exception e){throw new IllegalArgumentException("Cannot canonicalize JSON",e);}}
 private JsonNode sort(JsonNode n){if(n.isObject()){ObjectNode o=om.createObjectNode();java.util.ArrayList<String> names=new java.util.ArrayList<>();n.fieldNames().forEachRemaining(names::add);java.util.Collections.sort(names);for(String k:names)o.set(k,sort(n.get(k)));return o;}if(n.isArray()){ArrayNode a=om.createArrayNode();n.forEach(x->a.add(sort(x)));return a;}return n;}
 public String eventHash(long seq,java.util.UUID id,String type,String actor,String rt,String rid,String payload,java.time.Instant ts,String prev){return sha256(frame("v1",String.valueOf(seq),id.toString(),type,actor,rt,rid,payload,ts.toString(),prev));}
 public String recalc(AuditEvent e){return eventHash(e.getSequenceNumber(),e.getId(),e.getEventType(),e.getActorId(),e.getResourceType(),e.getResourceId(),e.getPayload(),e.getEventTimestamp(),e.getPreviousHash());}
 public String sha256(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(b);}catch(Exception e){throw new IllegalStateException(e);}}
 public String hmac(String key,String value){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.util.HexFormat.of().formatHex(m.doFinal(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private String frame(String...v){StringBuilder b=new StringBuilder();for(String s:v)b.append(s.getBytes(StandardCharsets.UTF_8).length).append(':').append(s);return b.toString();}}
